	// takes it out ("Добавить в левое меню").
	PinClub(context.Context, *PinClubRequest) (*emptypb.Empty, error)
	// The clubs in the caller's left menu that they still run.
	ListPinnedClubs(context.Context, *ListPinnedClubsRequest) (*ListPinnedClubsResponse, error)
	// What the caller is in each of up to 100 clubs; those they are not in
	// are left out.
	ListMyRoles(context.Context, *ListMyRolesRequest) (*ListMyRolesResponse, error)
	// Whether the caller may write on the club's wall, on their own behalf
	// or, with from_club, on the club's, or else suggest a post.
	CanPostOnWall(context.Context, *CanPostOnWallRequest) (*CanPostOnWallResponse, error)
	// Internal, for post: whether user_id keeps the wall of wall_id clean,
	// deleting and pinning others' posts and comments there: the club's
	// admins do. False for any other wall, a user's.
	CanModerateWall(context.Context, *CanModerateWallRequest) (*CanModerateWallResponse, error)
	// Internal, for post: the users who keep the wall of wall_id clean, the
	// owner and admins of the club, to hear about posts suggested there; up
	// to 100, the newest appointed first. None for any other wall.
	ListWallModerators(context.Context, *ListWallModeratorsRequest) (*ListWallModeratorsResponse, error)
	// Internal, for user: the user's page was deleted and not restored in
	// time; they leave every club. Idempotent.
	PurgeUser(context.Context, *PurgeUserRequest) (*emptypb.Empty, error)
